`,e.jsxs(t.p,{children:["Sources checked ",e.jsx(t.strong,{children:"2026-10-19"}),". Read-only review of Microsoft Playwright ",e.jsx(t.strong,{children:"v1.64.1"}),", whose ",e.jsx(t.a,{href:"https://api.github.com/repos/microsoft/playwright/git/ref/tags/v1.64.1",children:"tag"})," resolves to ",e.jsx(t.code,{children:"cfe490d941f992655948eee8fd4fd94e1c4234bf"}),". This selected release matches GameMap's declared development dependency, not a verified benchmark runtime. The repository ",e.jsx(t.a,{href:"https://github.com/microsoft/playwright/blob/cfe490d941f992655948eee8fd4fd94e1c4234bf/LICENSE",children:"license"})," is Apache-2.0; it does not clear browser binaries, tested games or their assets. No upstream code, browser or game was executed."]}),`
